cat > /tmp/probe/sfam/pred.awk <<'EOF'
function pl(w,  n2,n1,prev){
  n1=substr(w,length(w),1); n2=substr(w,length(w)-1,2); prev=substr(w,length(w)-1,1);
  if (n1=="y") { if (prev ~ /[aeiou]/) return w "s"; else return substr(w,1,length(w)-1) "ies"; }
  if (n2=="es") return w;
  if (n1=="s") return w "es";
  if (n2=="ch" || n2=="sh") return w "es";
  return w "s";
}
{ if ($2 != pl($1)) printf "%s\t%s\tPRED=%s\n",$1,$2,pl($1) }
EOF
cd /tmp/probe/sfam && awk -F'\t' -f pred.awk o_2let.tsv | tee dev_2let.txt | wc -l; cat dev_2let.txt
